package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create-owner request that is missing or blank in any of firstName, lastName,
 * address, city or telephone, before {@link BuildOwner} runs. Runs first so an incomplete
 * body is a 400 naming the offending fields. Also normalizes the telephone into E.164 form
 * (see {@link OwnerTelephone}), rejecting otherwise with a 400; the normalized value is
 * stored on the body so it is persisted and returned.
 * When an {@code email} is present it must be a syntactically valid address and is stored
 * lower-cased (rejected with 400 otherwise); an absent email is allowed.
 * Publishes the validated body for later steps.
 */
public class ValidateOwnerFields {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidOwnerTelephoneException, InvalidOwnerEmailException,
            DisposableOwnerEmailException, InvalidOwnerPostcodeException, FutureRegistrationDateException {
        // Normalize the address up front so the required-field check below rejects an address that
        // is blank after normalization, and the persisted/returned value is the normalized form.
        request.setAddress(OwnerAddress.normalize(request.getAddress()));
        List<String> missing = new ArrayList<>();
        checkField("firstName", request.getFirstName(), missing);
        checkField("lastName", request.getLastName(), missing);
        checkField("address", request.getAddress(), missing);
        checkField("city", request.getCity(), missing);
        checkField("telephone", request.getTelephone(), missing);
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
        OwnerEmail.normalize(request);
        OwnerPostcode.validate(request.getPostcode(), request.getCity());
        LocalDate registrationDate = request.getRegistrationDate();
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException("registrationDate must not be later than the server date");
        }
        validated.set(request);
    }

    private static void checkField(String name, String value, List<String> missing) {
        if (value == null || value.isBlank()) {
            missing.add(name);
        }
    }
}
=== OwnerHousehold ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Shared derivation of an owner's household identity. The {@code householdId} is now
 * <em>deterministic</em>: the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + "|" + postcode}. Owners with the same last name (compared
 * case-insensitively with collapsed whitespace) and the same postcode therefore resolve to
 * the same householdId automatically, without any creation-order back-fill.
 *
 * <p>Used by {@link AssignOwnerHousehold} (which stamps the id onto a new owner), by
 * {@link EnsureUniqueOwnerIdentity} (which blocks a second owner of an existing household) and
 * by {@link AssignOwnerPossibleDuplicate} (which treats fellow household members as declared,
 * not suspected, duplicates), so all three agree on exactly what a household is.
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /**
     * The deterministic {@code householdId} for the given last name and postcode, or
     * {@code null} when no postcode is supplied (an owner with no postcode has no household).
     */
    static String idFor(String lastName, String postcode) {
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        return id(normalizeName(lastName), postcode.trim());
    }

    /** Stable 12-char upper-hex identifier derived from the deterministic household key. */
    static String id(String normalizedLastName, String postcode) {
        String key = normalizedLastName + "|" + postcode;
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
    static String normalizeName(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
=== OwnerPostcode ===
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.rest.function.common.Localities;

/**
 * Validates an owner's optional {@code postcode}. A postcode is validated only when present:
 * an absent (null or blank) postcode is accepted, keeping the create/update request contract
 * backward-compatible. When present it must be exactly 4 digits and, for a city whose region is
 * in the fixed table (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), fall within that region's
 * range. A city with no known region accepts any 4-digit postcode.
 */
final class OwnerPostcode {

    private OwnerPostcode() {
    }

    /**
     * Validate the supplied postcode for the given city, throwing when it is present but invalid.
     * Does nothing when the postcode is absent.
     */
    static void validate(String postcode, String city) throws InvalidOwnerPostcodeException {
        if (postcode == null || postcode.isBlank()) {
            return; // optional when absent
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw new InvalidOwnerPostcodeException("Postcode must be 4 digits, but was: '" + postcode + "'");
        }
        int[] range = Localities.postcodeRange(Localities.region(city));
        if (range == null) {
            return; // city with no known region accepts any 4-digit postcode
        }
        int value = Integer.parseInt(postcode);
        if (value < range[0] || value > range[1]) {
            throw new InvalidOwnerPostcodeException("Postcode '" + postcode + "' is out of range "
                    + range[0] + "-" + range[1] + " for city '" + city + "'");
        }
    }
}

